using System.Reflection;using System.Windows;using System.Windows.Controls;using SuperDock;
class Check{[STAThread]static void Main(){var app=new App();app.InitializeComponent();app.ShutdownMode=ShutdownMode.OnExplicitShutdown;var type=typeof(App).Assembly.GetType("SuperDock.AppearanceWindow")!;foreach(var theme in new[]{"Light","Dark"}){var w=(Window)Activator.CreateInstance(type,new object[]{new MainWindow.Settings{ThemeMode=theme},(Action)(()=>{}),null,null,null})!;w.Show();w.UpdateLayout();var input=(TextBox)type.GetField("settingsSearch",BindingFlags.NonPublic|BindingFlags.Instance)!.GetValue(w)!;foreach(var text in new[]{"消息提醒","透明度","搜索设置 abc 123"}){input.Text=text;input.CaretIndex=text.Length;input.UpdateLayout();w.UpdateLayout();var glyph=input.GetRectFromCharacterIndex(0);if(input.ActualWidth<100||glyph.Height<15||glyph.Top<-.5||glyph.Bottom>input.ActualHeight+.5)throw new Exception($"Clipped text {text} bounds {glyph} viewport {input.ActualWidth}x{input.ActualHeight}");}Console.WriteLine("PASS Chinese/English full glyph height and search layout "+theme);w.Close();}app.Shutdown();}}
